function main(p, state) {
  var cells = p.cells || [];
  var c = state.container || {};
  var slots = c.slots || [];
  var type = String(c.type || 'none');
  var RESULT = 0;
  var GRID_FIRST = 1;
  var gridLastWide = 9;
  var playerFromWide = 10;
  var gridLastNarrow = 4;
  var playerFromNarrow = 9;
  var GRID_LAST = (type === 'crafting') ? gridLastWide : gridLastNarrow;
  var PLAYER_FROM = (type === 'crafting') ? playerFromWide : playerFromNarrow;
  var bySlot = {};
  for (var i = 0; i < slots.length; i++) {
    var s = slots[i];
    if (s && typeof s.slot === 'number' && s.id) { bySlot[s.slot] = s; }
  }
  function matcher(spec) {
    if (spec === 'planks') { return function (id) { return /^minecraft:[a-z_]+_planks$/.test(id); }; }
    if (spec === 'stick') { return function (id) { return id === 'minecraft:' + spec; }; }
    if (spec === 'log') {
      return function (id) {
        return /^minecraft:(stripped_)?[a-z_]+(_log|_wood|_stem|_hyphae)$/.test(id) || /^minecraft:(stripped_)?bamboo_block$/.test(id);
      };
    }
    return function (id) { return id === spec; };
  }
  var errors = [];
  var pending = [];
  var wanted = {};
  for (var a = 0; a < cells.length; a++) {
    var cell = cells[a];
    if (!cell || typeof cell.slot !== 'number') { continue; }
    wanted[cell.slot] = true;
    var m = matcher(cell.match);
    var existing = bySlot[cell.slot];
    if (existing) {
      if (m(existing.id)) { continue; }
      errors.push('grid slot ' + cell.slot + ' already holds ' + existing.id);
    } else {
      pending.push(cell);
    }
  }
  for (var g = GRID_FIRST; g <= GRID_LAST; g++) {
    if (wanted[g]) { continue; }
    if (bySlot[g]) { errors.push('grid slot ' + g + ' should be empty but holds ' + bySlot[g].id); }
  }
  var sources = [];
  for (var b = 0; b < slots.length; b++) {
    var src = slots[b];
    if (!src || !src.id || typeof src.slot !== 'number') { continue; }
    if (src.slot < PLAYER_FROM) { continue; }
    sources.push({ slot: src.slot, id: src.id, left: src.count || 0 });
  }
  sources.sort(function (x, y) { return x.slot - y.slot; });
  var use = {};
  var order = [];
  var missing = [];
  for (var q = 0; q < pending.length; q++) {
    var pc = pending[q];
    var pm = matcher(pc.match);
    var found = null;
    for (var k = 0; k < sources.length; k++) {
      if (sources[k].left > 0 && pm(sources[k].id)) { found = sources[k]; break; }
    }
    if (!found) { missing.push(pc.slot); continue; }
    found.left = found.left - 1;
    if (!use[found.slot]) { use[found.slot] = []; order.push(found.slot); }
    use[found.slot].push(pc.slot);
  }
  order.sort(function (x, y) { return x - y; });
  var clicks = [];
  for (var o = 0; o < order.length; o++) {
    var sslot = order[o];
    clicks.push({ slot: sslot, button: 0, clickType: 0 });
    var targets = use[sslot];
    for (var t = 0; t < targets.length; t++) {
      clicks.push({ slot: targets[t], button: 1, clickType: 0 });
    }
    clicks.push({ slot: sslot, button: 0, clickType: 0 });
  }
  var ok = errors.length === 0 && missing.length === 0;
  var reason = errors.slice();
  for (var z = 0; z < missing.length; z++) {
    reason.push('no matching item in player slots for grid slot ' + missing[z]);
  }
  if (!ok) { return { clicks: [], ok: false, reason: reason.join('; '), missing: missing }; }
  clicks.push({ slot: RESULT, button: 0, clickType: 1 });
  return { clicks: clicks, ok: true, reason: '', missing: [] };
}
